begin;
create view public.budget_dashboard_monthly with(security_invoker=true) as
with integrated as(select i.*,coalesce(cc.name,'Geral') cost_center_name from public.budget_integrated_overview i left join public.cost_centers cc on cc.tenant_id=i.tenant_id and cc.company_id=i.company_id and cc.id=i.cost_center_id), limits as(select tenant_id,company_id,cost_center_id,competence_month,sum(limit_amount)::numeric(18,2) limit_amount,sum(consumed_amount)::numeric(18,2) limit_consumed,sum(remaining_amount)::numeric(18,2) limit_remaining,count(*) filter(where limit_status='exceeded') exceeded_limits,count(*) filter(where limit_status='warning') warning_limits from public.budget_limit_control group by tenant_id,company_id,cost_center_id,competence_month), eng as(select tenant_id,company_id,competence,sum(projected_revenue)::numeric(18,2) engineering_projected_revenue from public.budget_engineering_projection group by tenant_id,company_id,competence) select i.tenant_id,i.company_id,i.cost_center_id,i.cost_center_name,i.competence_month,i.salary_projection,i.other_planned,i.total_planned_expense,i.actual_expense,i.actual_income,i.planned_remaining,coalesce(l.limit_amount,0)::numeric(18,2) limit_amount,coalesce(l.limit_consumed,0)::numeric(18,2) limit_consumed,coalesce(l.limit_remaining,0)::numeric(18,2) limit_remaining,coalesce(l.exceeded_limits,0)::bigint exceeded_limits,coalesce(l.warning_limits,0)::bigint warning_limits,coalesce(e.engineering_projected_revenue,0)::numeric(18,2) engineering_projected_revenue,case when i.total_planned_expense>0 then round(i.actual_expense*100/i.total_planned_expense,2) else 0 end budget_execution_percent,case when coalesce(l.exceeded_limits,0)>0 then 'critical' when coalesce(l.warning_limits,0)>0 then 'warning' when i.planned_remaining<0 then 'critical' else 'ok' end budget_status from integrated i left join limits l on l.tenant_id=i.tenant_id and l.company_id=i.company_id and l.cost_center_id is not distinct from i.cost_center_id and l.competence_month=i.competence_month left join eng e on e.tenant_id=i.tenant_id and e.company_id=i.company_id and e.competence=i.competence_month;
create view public.budget_dashboard_company with(security_invoker=true) as select tenant_id,company_id,competence_month,sum(salary_projection)::numeric(18,2) salary_projection,sum(other_planned)::numeric(18,2) other_planned,sum(total_planned_expense)::numeric(18,2) total_planned_expense,sum(actual_expense)::numeric(18,2) actual_expense,sum(actual_income)::numeric(18,2) actual_income,sum(planned_remaining)::numeric(18,2) planned_remaining,sum(limit_amount)::numeric(18,2) configured_limits,sum(limit_consumed)::numeric(18,2) limit_consumed,sum(limit_remaining)::numeric(18,2) limit_remaining,max(engineering_projected_revenue)::numeric(18,2) engineering_projected_revenue,sum(exceeded_limits)::bigint exceeded_limits,sum(warning_limits)::bigint warning_limits,case when sum(total_planned_expense)>0 then round(sum(actual_expense)*100/sum(total_planned_expense),2) else 0 end budget_execution_percent,case when sum(exceeded_limits)>0 or sum(planned_remaining)<0 then 'critical' when sum(warning_limits)>0 then 'warning' else 'ok' end budget_status from public.budget_dashboard_monthly group by tenant_id,company_id,competence_month;
create view public.budget_dashboard_annual with(security_invoker=true) as select tenant_id,company_id,date_trunc('year',competence_month)::date budget_year,sum(salary_projection)::numeric(18,2) salary_projection,sum(other_planned)::numeric(18,2) other_planned,sum(total_planned_expense)::numeric(18,2) total_planned_expense,sum(actual_expense)::numeric(18,2) actual_expense,sum(actual_income)::numeric(18,2) actual_income,sum(planned_remaining)::numeric(18,2) planned_remaining,sum(engineering_projected_revenue)::numeric(18,2) engineering_projected_revenue,sum(exceeded_limits)::bigint exceeded_limits,sum(warning_limits)::bigint warning_limits,case when sum(total_planned_expense)>0 then round(sum(actual_expense)*100/sum(total_planned_expense),2) else 0 end budget_execution_percent from public.budget_dashboard_company group by tenant_id,company_id,date_trunc('year',competence_month)::date;
commit;
